  ('workEconomy', $v$Work & Economy$v$, $v$Careers, business and the economy — essential for Task 2 and Part 3 discussion.$v$, 'topic', 'var(--warn)', 4),
  ('crimeLaw', $v$Crime & Law$v$, $v$Justice, punishment and policing — a classic Writing Task 2 and Part 3 topic.$v$, 'topic', '#475569', 5),
  ('societyCulture', $v$Society & Culture$v$, $v$Tradition, diversity and social change — high-value for Writing and Speaking.$v$, 'topic', '#0d9488', 6),
