  ('awl', $v$Academic Word List$v$, $v$Core high-frequency words from academic English — the backbone of Task 2 writing.$v$, 'function', 'var(--accent)', 10),
  ('linkers', $v$Linkers & Cohesion$v$, $v$Connectives for sequencing, contrasting and exemplifying — the glue of essays.$v$, 'function', 'var(--warn)', 11),
