from vocabulary_decks d
cross join (values
  ($v$curriculum$v$, 'n', $v$/kəˈrɪkjələm/$v$, $v$The subjects that make up a course of study at a school or college.$v$, $v$The national curriculum places a heavy emphasis on science and mathematics.$v$, array[$v$syllabus$v$, $v$programme$v$]::text[], '{}'::text[], '7.0'),
  ($v$rote learning$v$, 'phrase', $v$/rəʊt ˈlɜːnɪŋ/$v$, $v$Memorising information through repetition rather than understanding.$v$, $v$Critics argue that rote learning stifles a child’s natural curiosity.$v$, array[$v$memorisation$v$, $v$cramming$v$]::text[], array[$v$active learning$v$]::text[], '7.5'),
  ($v$literacy$v$, 'n', $v$/ˈlɪtərəsi/$v$, $v$The ability to read and write.$v$, $v$Adult literacy programmes have transformed employment prospects in rural areas.$v$, array[$v$reading ability$v$]::text[], array[$v$illiteracy$v$]::text[], '6.5'),
  ($v$vocational$v$, 'adj', $v$/vəʊˈkeɪʃənl/$v$, $v$Relating to training for a specific job or trade.$v$, $v$Vocational courses equip students with practical, job-ready skills.$v$, array[$v$practical$v$, $v$occupational$v$]::text[], array[$v$academic$v$]::text[], '7.0'),
  ($v$pedagogy$v$, 'n', $v$/ˈpedəɡɒdʒi/$v$, $v$The method and practice of teaching.$v$, $v$Modern pedagogy favours collaboration over passive listening.$v$, array[$v$teaching method$v$]::text[], '{}'::text[], '8.0'),
  ($v$truancy$v$, 'n', $v$/ˈtruːənsi/$v$, $v$The act of staying away from school without permission.$v$, $v$Schools have introduced fines to combat persistent truancy.$v$, array[$v$absenteeism$v$]::text[], array[$v$attendance$v$]::text[], '7.5'),
  ($v$holistic$v$, 'adj', $v$/həˈlɪstɪk/$v$, $v$Considering the whole person or system rather than just one part.$v$, $v$A holistic education nurtures emotional as well as academic growth.$v$, array[$v$comprehensive$v$, $v$all-round$v$]::text[], array[$v$narrow$v$]::text[], '7.5'),
  ($v$discipline$v$, 'n', $v$/ˈdɪsəplɪn/$v$, $v$Controlled, orderly behaviour, or training that produces it.$v$, $v$Strict discipline in the classroom can either focus or intimidate pupils.$v$, array[$v$order$v$, $v$self-control$v$]::text[], array[$v$disorder$v$]::text[], '6.5'),
  ($v$enrol$v$, 'v', $v$/ɪnˈrəʊl/$v$, $v$To officially register as a member or student.$v$, $v$Thousands of mature students enrol on online degrees each year.$v$, array[$v$register$v$, $v$sign up$v$]::text[], array[$v$withdraw$v$]::text[], '6.5'),
  ($v$scholarship$v$, 'n', $v$/ˈskɒləʃɪp/$v$, $v$A grant of money to support a student’s education.$v$, $v$She won a full scholarship to study engineering abroad.$v$, array[$v$grant$v$, $v$bursary$v$]::text[], '{}'::text[], '6.5'),
  ($v$curiosity$v$, 'n', $v$/ˌkjʊəriˈɒsəti/$v$, $v$A strong desire to learn or know something.$v$, $v$Good teachers spark curiosity rather than simply transmit facts.$v$, array[$v$inquisitiveness$v$, $v$interest$v$]::text[], array[$v$indifference$v$]::text[], '7.0'),
  ($v$rigorous$v$, 'adj', $v$/ˈrɪɡərəs/$v$, $v$Extremely thorough, careful and demanding.$v$, $v$Medical training is famously rigorous and competitive.$v$, array[$v$demanding$v$, $v$exacting$v$]::text[], array[$v$lax$v$, $v$lenient$v$]::text[], '7.5'),
  ($v$aptitude$v$, 'n', $v$/ˈæptɪtjuːd/$v$, $v$A natural ability or talent for something.$v$, $v$The test is designed to measure a candidate’s aptitude for languages.$v$, array[$v$talent$v$, $v$flair$v$]::text[], array[$v$inability$v$]::text[], '7.5'),
  ($v$interactive$v$, 'adj', $v$/ˌɪntərˈæktɪv/$v$, $v$Involving active participation between people or with technology.$v$, $v$Interactive whiteboards have made lessons far more engaging.$v$, array[$v$participatory$v$, $v$hands-on$v$]::text[], array[$v$passive$v$]::text[], '6.5'),
  ($v$comprehension$v$, 'n', $v$/ˌkɒmprɪˈhenʃn/$v$, $v$The ability to understand something.$v$, $v$Reading comprehension improves dramatically with daily practice.$v$, array[$v$understanding$v$, $v$grasp$v$]::text[], array[$v$confusion$v$]::text[], '6.5'),
  ($v$tuition$v$, 'n', $v$/tjuˈɪʃn/$v$, $v$Teaching, especially of an individual or small group; also course fees.$v$, $v$Private tuition has become a booming industry in many countries.$v$, array[$v$instruction$v$, $v$coaching$v$]::text[], '{}'::text[], '7.0'),
  ($v$underachieve$v$, 'v', $v$/ˌʌndərəˈtʃiːv/$v$, $v$To do less well than one is capable of.$v$, $v$Boys are statistically more likely to underachieve at school.$v$, array[$v$underperform$v$]::text[], array[$v$excel$v$]::text[], '7.5'),
  ($v$well-rounded$v$, 'adj', $v$/ˌwel ˈraʊndɪd/$v$, $v$Having a wide range of abilities, interests or experiences.$v$, $v$Universities increasingly seek well-rounded rather than narrowly gifted applicants.$v$, array[$v$versatile$v$, $v$balanced$v$]::text[], array[$v$one-dimensional$v$]::text[], '7.0'),
  ($v$mandatory$v$, 'adj', $v$/ˈmændətəri/$v$, $v$Required by law or rules; compulsory.$v$, $v$In most countries, schooling is mandatory until the age of sixteen.$v$, array[$v$compulsory$v$, $v$obligatory$v$]::text[], array[$v$optional$v$, $v$voluntary$v$]::text[], '7.0'),
  ($v$intellectual$v$, 'adj', $v$/ˌɪntəˈlektʃuəl/$v$, $v$Relating to the ability to think and understand ideas.$v$, $v$Debating clubs offer valuable intellectual stimulation.$v$, array[$v$cerebral$v$, $v$cognitive$v$]::text[], '{}'::text[], '7.0'),
  ($v$nurture$v$, 'v', $v$/ˈnɜːtʃə/$v$, $v$To care for and encourage the growth or development of someone.$v$, $v$Parents and teachers must work together to nurture a child’s talents.$v$, array[$v$foster$v$, $v$cultivate$v$]::text[], array[$v$neglect$v$, $v$stifle$v$]::text[], '7.5'),
  ($v$streaming$v$, 'n', $v$/ˈstriːmɪŋ/$v$, $v$Grouping pupils by ability into separate classes.$v$, $v$Streaming can motivate top students but discourage weaker ones.$v$, array[$v$setting$v$, $v$tracking$v$]::text[], array[$v$mixed-ability$v$]::text[], '7.5'),
  ($v$proficiency$v$, 'n', $v$/prəˈfɪʃnsi/$v$, $v$A high degree of skill or competence.$v$, $v$Employers now expect proficiency in at least one foreign language.$v$, array[$v$competence$v$, $v$mastery$v$]::text[], array[$v$incompetence$v$]::text[], '7.5'),
  ($v$curtail$v$, 'v', $v$/kɜːˈteɪl/$v$, $v$To reduce or restrict something.$v$, $v$Budget cuts have curtailed extracurricular activities in state schools.$v$, array[$v$restrict$v$, $v$cut back$v$]::text[], array[$v$expand$v$]::text[], '8.0'),
  ($v$fee-paying$v$, 'adj', $v$/ˈfiː ˌpeɪɪŋ/$v$, $v$Describing private schools that charge tuition.$v$, $v$Critics claim fee-paying schools entrench social inequality.$v$, array[$v$private$v$, $v$independent$v$]::text[], array[$v$state$v$]::text[], '7.0'),
  ($v$lifelong$v$, 'adj', $v$/ˈlaɪflɒŋ/$v$, $v$Continuing throughout a person’s life.$v$, $v$The internet has made lifelong learning accessible to almost everyone.$v$, array[$v$continuous$v$, $v$ongoing$v$]::text[], array[$v$short-term$v$]::text[], '6.5'),
  ($v$cognitive$v$, 'adj', $v$/ˈkɒɡnətɪv/$v$, $v$Relating to mental processes of thinking and learning.$v$, $v$Bilingual children often show enhanced cognitive flexibility.$v$, array[$v$mental$v$, $v$intellectual$v$]::text[], '{}'::text[], '8.0'),
  ($v$dropout$v$, 'n', $v$/ˈdrɒpaʊt/$v$, $v$A person who leaves school or a course before finishing.$v$, $v$High dropout rates often reflect deeper social problems.$v$, array[$v$quitter$v$, $v$leaver$v$]::text[], array[$v$graduate$v$]::text[], '7.0'),
  ($v$stimulating$v$, 'adj', $v$/ˈstɪmjəleɪtɪŋ/$v$, $v$Encouraging interest, thought or enthusiasm.$v$, $v$A stimulating classroom environment keeps young learners engaged.$v$, array[$v$engaging$v$, $v$inspiring$v$]::text[], array[$v$dull$v$, $v$tedious$v$]::text[], '7.0')
) as w(word, pos, ipa, def, ex, syn, ant, band)
