  ($v$biodiversity$v$, 'n', $v$/ˌbaɪəʊdaɪˈvɜːsəti/$v$, $v$The variety of plant and animal life in a habitat.$v$, $v$Protecting biodiversity is essential for a stable ecosystem.$v$, array[$v$variety of life$v$]::text[], '{}'::text[], '7.5'),
  ($v$renewable$v$, 'adj', $v$/rɪˈnjuːəbl/$v$, $v$Able to be replenished naturally, like solar or wind power.$v$, $v$Renewable sources now supply a third of the country’s electricity.$v$, array[$v$sustainable$v$, $v$green$v$]::text[], array[$v$finite$v$, $v$fossil$v$]::text[], '6.5'),
  ($v$degradation$v$, 'n', $v$/ˌdeɡrəˈdeɪʃn/$v$, $v$The process of damaging or lowering the quality of something.$v$, $v$Soil degradation is reducing crop yields across the region.$v$, array[$v$deterioration$v$, $v$decline$v$]::text[], array[$v$restoration$v$]::text[], '7.5'),
  ($v$carbon footprint$v$, 'phrase', $v$/ˈkɑːbən ˈfʊtprɪnt/$v$, $v$The total amount of greenhouse gases produced by an activity.$v$, $v$Cycling to work is a simple way to shrink your carbon footprint.$v$, array[$v$emissions impact$v$]::text[], '{}'::text[], '7.0'),
  ($v$conservation$v$, 'n', $v$/ˌkɒnsəˈveɪʃn/$v$, $v$The protection of nature and natural resources.$v$, $v$Wildlife conservation depends heavily on local community support.$v$, array[$v$preservation$v$, $v$protection$v$]::text[], array[$v$exploitation$v$]::text[], '6.5'),
  ($v$depletion$v$, 'n', $v$/dɪˈpliːʃn/$v$, $v$The reduction of a resource until it runs low.$v$, $v$The depletion of fish stocks endangers coastal economies.$v$, array[$v$exhaustion$v$, $v$reduction$v$]::text[], array[$v$replenishment$v$]::text[], '7.5'),
  ($v$ecosystem$v$, 'n', $v$/ˈiːkəʊsɪstəm/$v$, $v$A community of living things and their environment.$v$, $v$Coral reefs support some of the richest ecosystems on Earth.$v$, array[$v$habitat$v$, $v$biome$v$]::text[], '{}'::text[], '7.0'),
