  ($v$pollutant$v$, 'n', $v$/pəˈluːtənt/$v$, $v$A substance that contaminates air, water or soil.$v$, $v$Industrial pollutants have poisoned the river for decades.$v$, array[$v$contaminant$v$, $v$toxin$v$]::text[], '{}'::text[], '7.0'),
