  ($v$contaminate$v$, 'v', $v$/kənˈtæmɪneɪt/$v$, $v$To make something impure or poisonous.$v$, $v$Leaking pipelines can contaminate the local water supply.$v$, array[$v$pollute$v$, $v$taint$v$]::text[], array[$v$purify$v$]::text[], '7.0'),
  ($v$eco-friendly$v$, 'adj', $v$/ˈiːkəʊ ˈfrendli/$v$, $v$Not harmful to the environment.$v$, $v$The company has switched to eco-friendly packaging.$v$, array[$v$green$v$, $v$sustainable$v$]::text[], array[$v$polluting$v$]::text[], '6.5'),
  ($v$extinction$v$, 'n', $v$/ɪkˈstɪŋkʃn/$v$, $v$The state of a species no longer existing.$v$, $v$Several species face extinction within our lifetime.$v$, array[$v$dying out$v$, $v$eradication$v$]::text[], array[$v$survival$v$]::text[], '7.0'),
  ($v$drought$v$, 'n', $v$/draʊt/$v$, $v$A long period of abnormally low rainfall.$v$, $v$Prolonged drought has devastated the harvest this year.$v$, array[$v$dry spell$v$, $v$water shortage$v$]::text[], array[$v$flood$v$]::text[], '6.5'),
  ($v$exacerbate$v$, 'v', $v$/ɪɡˈzæsəbeɪt/$v$, $v$To make a problem or bad situation worse.$v$, $v$Burning coal will only exacerbate air pollution in cities.$v$, array[$v$aggravate$v$, $v$worsen$v$]::text[], array[$v$alleviate$v$, $v$ease$v$]::text[], '8.0'),
  ($v$scarcity$v$, 'n', $v$/ˈskeəsəti/$v$, $v$A shortage or insufficient supply of something.$v$, $v$Water scarcity could trigger conflicts in the coming decades.$v$, array[$v$shortage$v$, $v$dearth$v$]::text[], array[$v$abundance$v$]::text[], '7.5'),
  ($v$recycle$v$, 'v', $v$/ˌriːˈsaɪkl/$v$, $v$To process waste so it can be used again.$v$, $v$Households are encouraged to recycle glass, paper and plastic.$v$, array[$v$reuse$v$, $v$reprocess$v$]::text[], array[$v$discard$v$]::text[], '6.5'),
  ($v$fragile$v$, 'adj', $v$/ˈfrædʒaɪl/$v$, $v$Easily damaged or destroyed; delicate.$v$, $v$The Arctic is a fragile environment highly sensitive to warming.$v$, array[$v$delicate$v$, $v$vulnerable$v$]::text[], array[$v$robust$v$, $v$resilient$v$]::text[], '7.0'),
  ($v$sustainability$v$, 'n', $v$/səˌsteɪnəˈbɪləti/$v$, $v$The ability to maintain something without depleting resources.$v$, $v$Sustainability has become central to corporate strategy.$v$, array[$v$viability$v$]::text[], '{}'::text[], '7.5'),
  ($v$hazardous$v$, 'adj', $v$/ˈhæzədəs/$v$, $v$Dangerous or risky, especially to health.$v$, $v$Hazardous waste must be disposed of under strict regulation.$v$, array[$v$dangerous$v$, $v$perilous$v$]::text[], array[$v$safe$v$, $v$harmless$v$]::text[], '7.0'),
  ($v$replenish$v$, 'v', $v$/rɪˈplenɪʃ/$v$, $v$To fill something up again or restore a supply.$v$, $v$Aquifers take centuries to replenish once they are drained.$v$, array[$v$refill$v$, $v$restore$v$]::text[], array[$v$deplete$v$]::text[], '8.0'),
  ($v$arable$v$, 'adj', $v$/ˈærəbl/$v$, $v$Suitable for growing crops.$v$, $v$Climate change is shrinking the world’s arable land.$v$, array[$v$fertile$v$, $v$cultivable$v$]::text[], array[$v$barren$v$]::text[], '8.0'),
  ($v$catastrophic$v$, 'adj', $v$/ˌkætəˈstrɒfɪk/$v$, $v$Involving sudden, large-scale disaster.$v$, $v$Unchecked warming could have catastrophic consequences.$v$, array[$v$disastrous$v$, $v$devastating$v$]::text[], array[$v$harmless$v$]::text[], '7.5')
) as w(word, pos, ipa, def, ex, syn, ant, band)
where d.slug = 'environment'
