from vocabulary_decks d
cross join (values
  ($v$automation$v$, 'n', $v$/ˌɔːtəˈmeɪʃn/$v$, $v$The use of machines to do work previously done by people.$v$, $v$Automation is reshaping factories and threatening some jobs.$v$, array[$v$mechanisation$v$]::text[], array[$v$manual labour$v$]::text[], '7.0'),
  ($v$innovation$v$, 'n', $v$/ˌɪnəˈveɪʃn/$v$, $v$A new method, idea or product.$v$, $v$Constant innovation keeps technology companies ahead of rivals.$v$, array[$v$invention$v$, $v$breakthrough$v$]::text[], array[$v$stagnation$v$]::text[], '6.5'),
  ($v$obsolete$v$, 'adj', $v$/ˈɒbsəliːt/$v$, $v$No longer in use because something newer exists.$v$, $v$Smartphones have rendered many gadgets obsolete.$v$, array[$v$outdated$v$, $v$antiquated$v$]::text[], array[$v$current$v$, $v$modern$v$]::text[], '7.5'),
  ($v$cutting-edge$v$, 'adj', $v$/ˈkʌtɪŋ edʒ/$v$, $v$At the most advanced stage of development.$v$, $v$The lab uses cutting-edge artificial intelligence.$v$, array[$v$state-of-the-art$v$, $v$advanced$v$]::text[], array[$v$outdated$v$]::text[], '7.0'),
  ($v$surveillance$v$, 'n', $v$/səˈveɪləns/$v$, $v$Close observation, especially of a suspect or the public.$v$, $v$Cities are increasingly covered by surveillance cameras.$v$, array[$v$monitoring$v$, $v$observation$v$]::text[], '{}'::text[], '7.5'),
  ($v$connectivity$v$, 'n', $v$/ˌkɒnekˈtɪvəti/$v$, $v$The state of being connected, especially to the internet.$v$, $v$Rural areas still suffer from poor internet connectivity.$v$, array[$v$access$v$, $v$linkage$v$]::text[], '{}'::text[], '7.0'),
  ($v$addictive$v$, 'adj', $v$/əˈdɪktɪv/$v$, $v$Causing a strong, harmful urge to keep doing something.$v$, $v$Social media apps are deliberately designed to be addictive.$v$, array[$v$compulsive$v$, $v$habit-forming$v$]::text[], '{}'::text[], '6.5'),
  ($v$disruptive$v$, 'adj', $v$/dɪsˈrʌptɪv/$v$, $v$Radically changing an existing industry or market.$v$, $v$Streaming was a disruptive technology that destroyed video rental.$v$, array[$v$revolutionary$v$, $v$transformative$v$]::text[], '{}'::text[], '7.5'),
  ($v$glitch$v$, 'n', $v$/ɡlɪtʃ/$v$, $v$A small, temporary fault in a system.$v$, $v$A software glitch briefly took the banking app offline.$v$, array[$v$malfunction$v$, $v$bug$v$]::text[], '{}'::text[], '7.0'),
  ($v$encryption$v$, 'n', $v$/ɪnˈkrɪpʃn/$v$, $v$The process of converting data into a secure code.$v$, $v$End-to-end encryption protects messages from eavesdroppers.$v$, array[$v$encoding$v$]::text[], array[$v$decryption$v$]::text[], '8.0'),
  ($v$streamline$v$, 'v', $v$/ˈstriːmlaɪn/$v$, $v$To make a process simpler and more efficient.$v$, $v$The new platform streamlines the entire booking process.$v$, array[$v$simplify$v$, $v$optimise$v$]::text[], array[$v$complicate$v$]::text[], '7.5'),
  ($v$accessible$v$, 'adj', $v$/əkˈsesəbl/$v$, $v$Able to be reached, used or understood easily.$v$, $v$Online courses have made higher education far more accessible.$v$, array[$v$available$v$, $v$reachable$v$]::text[], array[$v$inaccessible$v$]::text[], '6.5'),
  ($v$malware$v$, 'n', $v$/ˈmælweə/$v$, $v$Software designed to damage or gain access to a computer.$v$, $v$A single click on the link installed malware on the network.$v$, array[$v$virus$v$, $v$spyware$v$]::text[], '{}'::text[], '7.0'),
  ($v$digital divide$v$, 'phrase', $v$/ˈdɪdʒɪtl dɪˈvaɪd/$v$, $v$The gap between those with and without internet access.$v$, $v$The pandemic exposed a stark digital divide between rich and poor.$v$, '{}'::text[], '{}'::text[], '7.5'),
  ($v$user-friendly$v$, 'adj', $v$/ˈjuːzə ˈfrendli/$v$, $v$Easy to use or understand.$v$, $v$The interface is clean, intuitive and user-friendly.$v$, array[$v$intuitive$v$, $v$accessible$v$]::text[], array[$v$complicated$v$]::text[], '6.5'),
  ($v$integrate$v$, 'v', $v$/ˈɪntɪɡreɪt/$v$, $v$To combine parts so they work together as a whole.$v$, $v$The app integrates seamlessly with your calendar and email.$v$, array[$v$combine$v$, $v$merge$v$]::text[], array[$v$separate$v$]::text[], '7.0'),
  ($v$anonymity$v$, 'n', $v$/ˌænəˈnɪməti/$v$, $v$The state of being unknown or unnamed.$v$, $v$Online anonymity can encourage abusive behaviour.$v$, array[$v$namelessness$v$]::text[], array[$v$identity$v$]::text[], '8.0'),
  ($v$artificial intelligence$v$, 'phrase', $v$/ˌɑːtɪˈfɪʃl ɪnˈtelɪdʒəns/$v$, $v$Computer systems able to perform tasks needing human intelligence.$v$, $v$Artificial intelligence is now used to diagnose certain diseases.$v$, array[$v$AI$v$, $v$machine learning$v$]::text[], '{}'::text[], '7.0'),
  ($v$versatile$v$, 'adj', $v$/ˈvɜːsətaɪl/$v$, $v$Able to adapt or be used for many purposes.$v$, $v$The device is remarkably versatile, doubling as a camera and phone.$v$, array[$v$adaptable$v$, $v$multipurpose$v$]::text[], array[$v$limited$v$]::text[], '7.5'),
  ($v$data breach$v$, 'phrase', $v$/ˈdeɪtə briːtʃ/$v$, $v$An incident where confidential data is accessed illegally.$v$, $v$The data breach exposed millions of customers’ passwords.$v$, array[$v$leak$v$, $v$hack$v$]::text[], '{}'::text[], '7.0'),
  ($v$intuitive$v$, 'adj', $v$/ɪnˈtjuːɪtɪv/$v$, $v$Easy to understand or use without instruction.$v$, $v$Good design feels intuitive even to first-time users.$v$, array[$v$instinctive$v$, $v$user-friendly$v$]::text[], array[$v$confusing$v$]::text[], '7.5'),
  ($v$redundant$v$, 'adj', $v$/rɪˈdʌndənt/$v$, $v$No longer needed or useful; superfluous.$v$, $v$Automation has made some clerical roles redundant.$v$, array[$v$superfluous$v$, $v$unnecessary$v$]::text[], array[$v$essential$v$]::text[], '7.5'),
  ($v$proliferate$v$, 'v', $v$/prəˈlɪfəreɪt/$v$, $v$To increase rapidly in number.$v$, $v$Fake news sites proliferated during the election.$v$, array[$v$multiply$v$, $v$mushroom$v$]::text[], array[$v$dwindle$v$]::text[], '8.0'),
  ($v$seamless$v$, 'adj', $v$/ˈsiːmləs/$v$, $v$Smooth and continuous, with no awkward gaps.$v$, $v$The update offers a seamless transition between devices.$v$, array[$v$smooth$v$, $v$fluid$v$]::text[], array[$v$disjointed$v$]::text[], '7.5'),
  ($v$gadget$v$, 'n', $v$/ˈɡædʒɪt/$v$, $v$A small, clever mechanical or electronic device.$v$, $v$The shop is full of gadgets that few people actually need.$v$, array[$v$device$v$, $v$gizmo$v$]::text[], '{}'::text[], '6.5'),
  ($v$outdated$v$, 'adj', $v$/ˌaʊtˈdeɪtɪd/$v$, $v$Old-fashioned and no longer useful.$v$, $v$Many schools still rely on outdated computer equipment.$v$, array[$v$obsolete$v$, $v$antiquated$v$]::text[], array[$v$modern$v$, $v$current$v$]::text[], '6.5'),
  ($v$revolutionise$v$, 'v', $v$/ˌrevəˈluːʃənaɪz/$v$, $v$To change something completely and fundamentally.$v$, $v$The smartphone revolutionised the way we communicate.$v$, array[$v$transform$v$, $v$overhaul$v$]::text[], '{}'::text[], '7.5'),
  ($v$screen time$v$, 'phrase', $v$/ˈskriːn taɪm/$v$, $v$Time spent using a device with a screen.$v$, $v$Doctors warn that excessive screen time harms children’s sleep.$v$, '{}'::text[], '{}'::text[], '6.5'),
  ($v$cyberbullying$v$, 'n', $v$/ˈsaɪbəˌbʊliɪŋ/$v$, $v$The use of digital platforms to harass or intimidate.$v$, $v$Schools now run workshops to tackle cyberbullying.$v$, array[$v$online harassment$v$]::text[], '{}'::text[], '7.0')
) as w(word, pos, ipa, def, ex, syn, ant, band)
where d.slug = 'technology'
on conflict (deck_id, word) do nothing;

-- ── Health & Lifestyle (29) ──
insert into vocabulary_words (deck_id, word, part_of_speech, ipa, definition, example, synonyms, antonyms, band_level)
select d.id, w.word, w.pos, w.ipa, w.def, w.ex, w.syn, w.ant, w.band
from vocabulary_decks d
cross join (values
  ($v$sedentary$v$, 'adj', $v$/ˈsedntri/$v$, $v$Involving little physical activity; spent sitting down.$v$, $v$A sedentary lifestyle is linked to obesity and heart disease.$v$, array[$v$inactive$v$, $v$desk-bound$v$]::text[], array[$v$active$v$]::text[], '7.5'),
  ($v$nutritious$v$, 'adj', $v$/njuˈtrɪʃəs/$v$, $v$Containing substances that nourish the body.$v$, $v$Children need a balanced, nutritious diet to grow properly.$v$, array[$v$nourishing$v$, $v$wholesome$v$]::text[], array[$v$unhealthy$v$]::text[], '6.5'),
  ($v$epidemic$v$, 'n', $v$/ˌepɪˈdemɪk/$v$, $v$A widespread occurrence of a disease in a community.$v$, $v$Health officials struggled to contain the flu epidemic.$v$, array[$v$outbreak$v$, $v$plague$v$]::text[], '{}'::text[], '7.0'),
  ($v$well-being$v$, 'n', $v$/ˈwel ˈbiːɪŋ/$v$, $v$The state of being comfortable, healthy and happy.$v$, $v$Employers are paying more attention to staff well-being.$v$, array[$v$welfare$v$, $v$wellness$v$]::text[], '{}'::text[], '6.5'),
  ($v$preventive$v$, 'adj', $v$/prɪˈventɪv/$v$, $v$Designed to stop something, especially illness, before it happens.$v$, $v$Preventive medicine reduces the long-term burden on hospitals.$v$, array[$v$precautionary$v$, $v$protective$v$]::text[], array[$v$curative$v$]::text[], '7.5'),
  ($v$chronic$v$, 'adj', $v$/ˈkrɒnɪk/$v$, $v$Persisting for a long time or constantly recurring.$v$, $v$Diabetes is a chronic condition requiring lifelong management.$v$, array[$v$persistent$v$, $v$long-term$v$]::text[], array[$v$acute$v$, $v$temporary$v$]::text[], '7.0'),
  ($v$obesity$v$, 'n', $v$/əʊˈbiːsəti/$v$, $v$The condition of being extremely overweight.$v$, $v$Childhood obesity has tripled over the past generation.$v$, array[$v$excess weight$v$]::text[], '{}'::text[], '6.5'),
  ($v$immunity$v$, 'n', $v$/ɪˈmjuːnəti/$v$, $v$The body’s ability to resist a particular infection.$v$, $v$Vaccination builds immunity against serious diseases.$v$, array[$v$resistance$v$]::text[], array[$v$susceptibility$v$]::text[], '7.0'),
  ($v$detrimental$v$, 'adj', $v$/ˌdetrɪˈmentl/$v$, $v$Tending to cause harm or damage.$v$, $v$Excessive sugar is detrimental to both teeth and waistlines.$v$, array[$v$harmful$v$, $v$damaging$v$]::text[], array[$v$beneficial$v$]::text[], '7.5'),
  ($v$rehabilitation$v$, 'n', $v$/ˌriːəˌbɪlɪˈteɪʃn/$v$, $v$The process of restoring health or normal life after illness.$v$, $v$Physiotherapy is central to rehabilitation after surgery.$v$, array[$v$recovery$v$, $v$recuperation$v$]::text[], '{}'::text[], '7.5'),
  ($v$contagious$v$, 'adj', $v$/kənˈteɪdʒəs/$v$, $v$Able to be spread by direct or indirect contact.$v$, $v$Measles is highly contagious among unvaccinated children.$v$, array[$v$infectious$v$, $v$communicable$v$]::text[], array[$v$non-infectious$v$]::text[], '7.0'),
  ($v$holistic$v$, 'adj', $v$/həˈlɪstɪk/$v$, $v$Treating the whole person, including mind and lifestyle.$v$, $v$The clinic takes a holistic approach to chronic pain.$v$, array[$v$integrated$v$, $v$all-round$v$]::text[], array[$v$narrow$v$]::text[], '7.5'),
  ($v$malnutrition$v$, 'n', $v$/ˌmælnjuˈtrɪʃn/$v$, $v$Poor health caused by an inadequate or unbalanced diet.$v$, $v$Millions of children still suffer from malnutrition.$v$, array[$v$undernourishment$v$]::text[], array[$v$nourishment$v$]::text[], '7.5'),
  ($v$ailment$v$, 'n', $v$/ˈeɪlmənt/$v$, $v$A minor illness or health problem.$v$, $v$Common ailments such as colds rarely need antibiotics.$v$, array[$v$illness$v$, $v$complaint$v$]::text[], '{}'::text[], '7.0'),
  ($v$therapeutic$v$, 'adj', $v$/ˌθerəˈpjuːtɪk/$v$, $v$Having a healing or relaxing effect.$v$, $v$Gardening can have a genuinely therapeutic effect on the mind.$v$, array[$v$healing$v$, $v$restorative$v$]::text[], array[$v$harmful$v$]::text[], '8.0'),
  ($v$susceptible$v$, 'adj', $v$/səˈseptəbl/$v$, $v$Likely to be affected by something, especially illness.$v$, $v$The elderly are particularly susceptible to winter infections.$v$, array[$v$vulnerable$v$, $v$prone$v$]::text[], array[$v$resistant$v$, $v$immune$v$]::text[], '7.5'),
  ($v$life expectancy$v$, 'phrase', $v$/laɪf ɪkˈspektənsi/$v$, $v$The average period a person is expected to live.$v$, $v$Better healthcare has raised life expectancy worldwide.$v$, '{}'::text[], '{}'::text[], '6.5'),
  ($v$fatigue$v$, 'n', $v$/fəˈtiːɡ/$v$, $v$Extreme tiredness from exertion or illness.$v$, $v$Long shifts leave many nurses suffering from chronic fatigue.$v$, array[$v$exhaustion$v$, $v$tiredness$v$]::text[], array[$v$energy$v$]::text[], '7.0'),
  ($v$abstain$v$, 'v', $v$/əbˈsteɪn/$v$, $v$To choose not to do or consume something.$v$, $v$Athletes are advised to abstain from alcohol during training.$v$, array[$v$refrain$v$, $v$avoid$v$]::text[], array[$v$indulge$v$]::text[], '8.0'),
  ($v$outbreak$v$, 'n', $v$/ˈaʊtbreɪk/$v$, $v$The sudden start of something unwelcome, such as disease.$v$, $v$An outbreak of cholera followed the floods.$v$, array[$v$epidemic$v$, $v$eruption$v$]::text[], '{}'::text[], '7.0'),
  ($v$balanced diet$v$, 'phrase', $v$/ˈbælənst ˈdaɪət/$v$, $v$A diet containing the right variety and amounts of food.$v$, $v$A balanced diet is the foundation of good health.$v$, '{}'::text[], '{}'::text[], '6.5'),
  ($v$invigorating$v$, 'adj', $v$/ɪnˈvɪɡəreɪtɪŋ/$v$, $v$Making one feel healthy, fresh and energetic.$v$, $v$An early morning swim is wonderfully invigorating.$v$, array[$v$refreshing$v$, $v$energising$v$]::text[], array[$v$tiring$v$]::text[], '8.0'),
  ($v$deteriorate$v$, 'v', $v$/dɪˈtɪəriəreɪt/$v$, $v$To become progressively worse.$v$, $v$Without treatment, her condition rapidly deteriorated.$v$, array[$v$worsen$v$, $v$decline$v$]::text[], array[$v$improve$v$, $v$recover$v$]::text[], '7.5'),
  ($v$hygiene$v$, 'n', $v$/ˈhaɪdʒiːn/$v$, $v$Practices that maintain health and prevent disease.$v$, $v$Good hand hygiene dramatically reduces infection rates.$v$, array[$v$cleanliness$v$, $v$sanitation$v$]::text[], '{}'::text[], '6.5'),
  ($v$addiction$v$, 'n', $v$/əˈdɪkʃn/$v$, $v$The condition of being unable to stop using something harmful.$v$, $v$Smartphone addiction is a growing concern among teenagers.$v$, array[$v$dependency$v$]::text[], '{}'::text[], '6.5'),
  ($v$robust$v$, 'adj', $v$/rəʊˈbʌst/$v$, $v$Strong and healthy; not easily damaged.$v$, $v$Regular exercise keeps the immune system robust.$v$, array[$v$sturdy$v$, $v$vigorous$v$]::text[], array[$v$frail$v$, $v$fragile$v$]::text[], '7.5'),
  ($v$moderation$v$, 'n', $v$/ˌmɒdəˈreɪʃn/$v$, $v$The avoidance of excess; keeping within sensible limits.$v$, $v$Most foods are fine when eaten in moderation.$v$, array[$v$restraint$v$, $v$temperance$v$]::text[], array[$v$excess$v$]::text[], '7.0'),
  ($v$ward off$v$, 'phrase', $v$/wɔːd ɒf/$v$, $v$To prevent something harmful from affecting you.$v$, $v$A diet rich in fruit may help ward off illness.$v$, array[$v$fend off$v$, $v$avert$v$]::text[], '{}'::text[], '7.5'),
  ($v$longevity$v$, 'n', $v$/lɒnˈdʒevəti/$v$, $v$Long life or duration.$v$, $v$Researchers link the population’s longevity to its diet.$v$, array[$v$long life$v$]::text[], '{}'::text[], '8.0')
) as w(word, pos, ipa, def, ex, syn, ant, band)
where d.slug = 'health'
on conflict (deck_id, word) do nothing;

-- ── Work & Economy (29) ──
insert into vocabulary_words (deck_id, word, part_of_speech, ipa, definition, example, synonyms, antonyms, band_level)
select d.id, w.word, w.pos, w.ipa, w.def, w.ex, w.syn, w.ant, w.band
from vocabulary_decks d
cross join (values
  ($v$unemployment$v$, 'n', $v$/ˌʌnɪmˈplɔɪmənt/$v$, $v$The state of not having a paid job.$v$, $v$Rising unemployment puts pressure on welfare systems.$v$, array[$v$joblessness$v$]::text[], array[$v$employment$v$]::text[], '6.5'),
  ($v$entrepreneur$v$, 'n', $v$/ˌɒntrəprəˈnɜː/$v$, $v$A person who sets up a business, taking financial risks.$v$, $v$Young entrepreneurs are reshaping the technology sector.$v$, array[$v$founder$v$, $v$businessperson$v$]::text[], '{}'::text[], '7.0'),
  ($v$recession$v$, 'n', $v$/rɪˈseʃn/$v$, $v$A period of temporary economic decline.$v$, $v$Many small firms collapsed during the recession.$v$, array[$v$downturn$v$, $v$slump$v$]::text[], array[$v$boom$v$, $v$recovery$v$]::text[], '7.0'),
  ($v$lucrative$v$, 'adj', $v$/ˈluːkrətɪv/$v$, $v$Producing a great deal of profit.$v$, $v$Software development remains a highly lucrative career.$v$, array[$v$profitable$v$, $v$well-paid$v$]::text[], array[$v$unprofitable$v$]::text[], '7.5'),
  ($v$workforce$v$, 'n', $v$/ˈwɜːkfɔːs/$v$, $v$The people available for or engaged in work.$v$, $v$Automation is transforming the skills the workforce needs.$v$, array[$v$labour force$v$, $v$staff$v$]::text[], '{}'::text[], '6.5'),
  ($v$incentive$v$, 'n', $v$/ɪnˈsentɪv/$v$, $v$Something that motivates or encourages action.$v$, $v$Tax breaks act as an incentive for firms to invest.$v$, array[$v$motivation$v$, $v$inducement$v$]::text[], array[$v$deterrent$v$]::text[], '7.5'),
  ($v$redundancy$v$, 'n', $v$/rɪˈdʌndənsi/$v$, $v$The loss of a job because it is no longer needed.$v$, $v$The factory closure led to hundreds of redundancies.$v$, array[$v$layoff$v$, $v$dismissal$v$]::text[], '{}'::text[], '7.5'),
  ($v$productivity$v$, 'n', $v$/ˌprɒdʌkˈtɪvəti/$v$, $v$The rate at which goods or work are produced.$v$, $v$Flexible hours can actually boost productivity.$v$, array[$v$efficiency$v$, $v$output$v$]::text[], '{}'::text[], '7.0'),
  ($v$remuneration$v$, 'n', $v$/rɪˌmjuːnəˈreɪʃn/$v$, $v$Payment or compensation for work or services.$v$, $v$The role offers generous remuneration and benefits.$v$, array[$v$pay$v$, $v$salary$v$]::text[], '{}'::text[], '8.0'),
  ($v$outsource$v$, 'v', $v$/ˈaʊtsɔːs/$v$, $v$To pay an outside company to do work internally done.$v$, $v$Many firms outsource customer service to cut costs.$v$, array[$v$contract out$v$, $v$subcontract$v$]::text[], array[$v$insource$v$]::text[], '7.5'),
  ($v$stagnant$v$, 'adj', $v$/ˈstæɡnənt/$v$, $v$Not growing, developing or progressing.$v$, $v$Wages have remained stagnant despite rising prices.$v$, array[$v$static$v$, $v$flat$v$]::text[], array[$v$booming$v$, $v$growing$v$]::text[], '7.5'),
  ($v$recruitment$v$, 'n', $v$/rɪˈkruːtmənt/$v$, $v$The process of finding and hiring new staff.$v$, $v$The company has frozen recruitment until next year.$v$, array[$v$hiring$v$]::text[], '{}'::text[], '6.5'),
  ($v$monopoly$v$, 'n', $v$/məˈnɒpəli/$v$, $v$Exclusive control of a market by one supplier.$v$, $v$Regulators worry that the merger could create a monopoly.$v$, array[$v$domination$v$]::text[], array[$v$competition$v$]::text[], '7.5'),
  ($v$expertise$v$, 'n', $v$/ˌekspɜːˈtiːz/$v$, $v$Expert skill or knowledge in a particular field.$v$, $v$Foreign firms are hired for their technical expertise.$v$, array[$v$proficiency$v$, $v$know-how$v$]::text[], array[$v$inexperience$v$]::text[], '7.0'),
  ($v$fluctuate$v$, 'v', $v$/ˈflʌktʃueɪt/$v$, $v$To rise and fall irregularly.$v$, $v$Oil prices fluctuate in response to global events.$v$, array[$v$vary$v$, $v$oscillate$v$]::text[], array[$v$stabilise$v$]::text[], '7.5'),
  ($v$self-employed$v$, 'adj', $v$/ˌself ɪmˈplɔɪd/$v$, $v$Working for oneself rather than an employer.$v$, $v$The number of self-employed workers has surged online.$v$, array[$v$freelance$v$, $v$independent$v$]::text[], array[$v$salaried$v$]::text[], '6.5'),
  ($v$subsidy$v$, 'n', $v$/ˈsʌbsədi/$v$, $v$Money paid by a government to support an industry.$v$, $v$Farmers depend on subsidies to stay in business.$v$, array[$v$grant$v$, $v$support$v$]::text[], '{}'::text[], '7.5'),
  ($v$thrive$v$, 'v', $v$/θraɪv/$v$, $v$To grow, develop or be successful.$v$, $v$Small businesses thrive when red tape is reduced.$v$, array[$v$flourish$v$, $v$prosper$v$]::text[], array[$v$struggle$v$, $v$fail$v$]::text[], '7.0'),
  ($v$affluent$v$, 'adj', $v$/ˈæfluənt/$v$, $v$Having a great deal of money; wealthy.$v$, $v$The policy mainly benefits the most affluent households.$v$, array[$v$wealthy$v$, $v$prosperous$v$]::text[], array[$v$poor$v$, $v$deprived$v$]::text[], '7.5'),
  ($v$workload$v$, 'n', $v$/ˈwɜːkləʊd/$v$, $v$The amount of work to be done by someone.$v$, $v$An unmanageable workload often leads to burnout.$v$, array[$v$burden$v$]::text[], '{}'::text[], '6.5'),
  ($v$vacancy$v$, 'n', $v$/ˈveɪkənsi/$v$, $v$A job position that is available.$v$, $v$The firm advertised several vacancies in marketing.$v$, array[$v$opening$v$, $v$position$v$]::text[], '{}'::text[], '6.5'),
