  ($v$autonomy$v$, 'n', $v$/ɔːˈtɒnəmi/$v$, $v$The right or condition of self-government.$v$, $v$The region was granted greater political autonomy.$v$, array[$v$independence$v$, $v$self-rule$v$]::text[], array[$v$dependence$v$]::text[], '8.0'),
  ($v$referendum$v$, 'n', $v$/ˌrefəˈrendəm/$v$, $v$A direct public vote on a single political question.$v$, $v$The constitution was changed by national referendum.$v$, array[$v$public vote$v$, $v$plebiscite$v$]::text[], '{}'::text[], '7.5'),
  ($v$regulate$v$, 'v', $v$/ˈreɡjuleɪt/$v$, $v$To control an activity by means of rules.$v$, $v$Governments are racing to regulate artificial intelligence.$v$, array[$v$control$v$, $v$govern$v$]::text[], array[$v$deregulate$v$]::text[], '7.0'),
  ($v$welfare$v$, 'n', $v$/ˈwelfeə/$v$, $v$Government support for those in need; well-being.$v$, $v$The welfare system protects the most vulnerable citizens.$v$, array[$v$benefits$v$, $v$social security$v$]::text[], '{}'::text[], '6.5'),
  ($v$propaganda$v$, 'n', $v$/ˌprɒpəˈɡændə/$v$, $v$Biased information used to promote a political cause.$v$, $v$State media flooded the country with propaganda.$v$, array[$v$misinformation$v$, $v$spin$v$]::text[], '{}'::text[], '7.5'),
  ($v$advocate$v$, 'v', $v$/ˈædvəkeɪt/$v$, $v$To publicly support or recommend something.$v$, $v$Many economists advocate higher taxes on carbon.$v$, array[$v$support$v$, $v$champion$v$]::text[], array[$v$oppose$v$]::text[], '7.5'),
  ($v$interdependence$v$, 'n', $v$/ˌɪntədɪˈpendəns/$v$, $v$A state of mutual reliance between parties.$v$, $v$Global trade has created deep economic interdependence.$v$, array[$v$mutual reliance$v$]::text[], array[$v$independence$v$]::text[], '8.0'),
  ($v$austerity$v$, 'n', $v$/ɔːˈsterəti/$v$, $v$Severe government measures to reduce spending.$v$, $v$Years of austerity left public services underfunded.$v$, array[$v$cutbacks$v$, $v$belt-tightening$v$]::text[], array[$v$stimulus$v$]::text[], '8.0'),
  ($v$transparency$v$, 'n', $v$/trænsˈpærənsi/$v$, $v$Openness and honesty in conducting affairs.$v$, $v$Citizens are calling for greater transparency in spending.$v$, array[$v$openness$v$, $v$candour$v$]::text[], array[$v$secrecy$v$]::text[], '7.5'),
  ($v$sanction$v$, 'n', $v$/ˈsæŋkʃn/$v$, $v$A penalty, often economic, imposed on a country.$v$, $v$International sanctions crippled the regime’s economy.$v$, array[$v$penalty$v$, $v$embargo$v$]::text[], array[$v$reward$v$]::text[], '7.5'),
  ($v$governance$v$, 'n', $v$/ˈɡʌvənəns/$v$, $v$The way in which an organisation or country is run.$v$, $v$Good governance attracts foreign investment.$v$, array[$v$administration$v$, $v$management$v$]::text[], '{}'::text[], '8.0'),
  ($v$centralised$v$, 'adj', $v$/ˈsentrəlaɪzd/$v$, $v$Controlled by a single central authority.$v$, $v$A heavily centralised system can ignore local needs.$v$, array[$v$concentrated$v$]::text[], array[$v$decentralised$v$]::text[], '7.5'),
  ($v$mandate$v$, 'n', $v$/ˈmændeɪt/$v$, $v$Authority to act, granted by an electorate.$v$, $v$The party claimed a clear mandate for reform.$v$, array[$v$authority$v$, $v$authorisation$v$]::text[], '{}'::text[], '8.0'),
  ($v$repression$v$, 'n', $v$/rɪˈpreʃn/$v$, $v$The use of force to control or subdue people.$v$, $v$The protests were met with brutal repression.$v$, array[$v$oppression$v$, $v$suppression$v$]::text[], array[$v$freedom$v$]::text[], '7.5'),
  ($v$migration$v$, 'n', $v$/maɪˈɡreɪʃn/$v$, $v$The movement of people from one place to another.$v$, $v$Economic migration reshapes both home and host countries.$v$, array[$v$movement$v$, $v$relocation$v$]::text[], '{}'::text[], '6.5'),
  ($v$coalition$v$, 'n', $v$/ˌkəʊəˈlɪʃn/$v$, $v$A temporary alliance, especially of political parties.$v$, $v$A fragile coalition formed after the election.$v$, array[$v$alliance$v$, $v$partnership$v$]::text[], '{}'::text[], '7.5'),
  ($v$infrastructure$v$, 'n', $v$/ˈɪnfrəstrʌktʃə/$v$, $v$Basic physical systems such as roads and power.$v$, $v$Investment in infrastructure boosts long-term growth.$v$, array[$v$facilities$v$, $v$framework$v$]::text[], '{}'::text[], '7.0'),
  ($v$exploitation$v$, 'n', $v$/ˌeksplɔɪˈteɪʃn/$v$, $v$Unfair use of people or resources for profit.$v$, $v$Critics highlight the exploitation of cheap overseas labour.$v$, array[$v$abuse$v$, $v$misuse$v$]::text[], array[$v$fair treatment$v$]::text[], '7.5'),
  ($v$stability$v$, 'n', $v$/stəˈbɪləti/$v$, $v$The state of being steady and not likely to change.$v$, $v$Political stability is vital for economic confidence.$v$, array[$v$steadiness$v$, $v$security$v$]::text[], array[$v$instability$v$]::text[], '6.5'),
  ($v$protectionism$v$, 'n', $v$/prəˈtekʃənɪzəm/$v$, $v$Shielding domestic industries through trade barriers.$v$, $v$Rising protectionism threatens global supply chains.$v$, array[$v$trade barriers$v$]::text[], array[$v$free trade$v$]::text[], '8.5'),
  ($v$unify$v$, 'v', $v$/ˈjuːnɪfaɪ/$v$, $v$To bring together to form a single unit.$v$, $v$A common currency was meant to unify the continent.$v$, array[$v$unite$v$, $v$merge$v$]::text[], array[$v$divide$v$]::text[], '7.0')
