where d.slug = 'government'
on conflict (deck_id, word) do nothing;

-- ── Media & Advertising (29) ──
insert into vocabulary_words (deck_id, word, part_of_speech, ipa, definition, example, synonyms, antonyms, band_level)
select d.id, w.word, w.pos, w.ipa, w.def, w.ex, w.syn, w.ant, w.band
from vocabulary_decks d
cross join (values
  ($v$influential$v$, 'adj', $v$/ˌɪnfluˈenʃl/$v$, $v$Having great influence on people or events.$v$, $v$Social media stars are now hugely influential among teenagers.$v$, array[$v$powerful$v$, $v$persuasive$v$]::text[], array[$v$insignificant$v$]::text[], '7.0'),
  ($v$sensationalism$v$, 'n', $v$/senˈseɪʃənəlɪzəm/$v$, $v$Presenting news in a shocking way to attract attention.$v$, $v$Tabloid sensationalism distorts public understanding.$v$, array[$v$exaggeration$v$]::text[], array[$v$restraint$v$]::text[], '8.0'),
  ($v$bias$v$, 'n', $v$/ˈbaɪəs/$v$, $v$A tendency to favour one side unfairly.$v$, $v$Readers should be alert to political bias in reporting.$v$, array[$v$partiality$v$, $v$slant$v$]::text[], array[$v$objectivity$v$]::text[], '7.0'),
  ($v$coverage$v$, 'n', $v$/ˈkʌvərɪdʒ/$v$, $v$The reporting of an event by the media.$v$, $v$The election received round-the-clock news coverage.$v$, array[$v$reporting$v$]::text[], '{}'::text[], '6.5'),
  ($v$manipulate$v$, 'v', $v$/məˈnɪpjuleɪt/$v$, $v$To control or influence cleverly or unfairly.$v$, $v$Advertisers manipulate emotions to sell products.$v$, array[$v$exploit$v$, $v$influence$v$]::text[], '{}'::text[], '7.5'),
  ($v$credible$v$, 'adj', $v$/ˈkredəbl/$v$, $v$Able to be believed; convincing.$v$, $v$Always check whether a source is genuinely credible.$v$, array[$v$believable$v$, $v$reliable$v$]::text[], array[$v$dubious$v$]::text[], '7.0'),
  ($v$misinformation$v$, 'n', $v$/ˌmɪsɪnfəˈmeɪʃn/$v$, $v$False or inaccurate information, especially online.$v$, $v$Misinformation spreads faster than verified facts.$v$, array[$v$falsehood$v$, $v$fake news$v$]::text[], array[$v$truth$v$]::text[], '7.5'),
  ($v$endorse$v$, 'v', $v$/ɪnˈdɔːs/$v$, $v$To publicly declare approval or support, especially in ads.$v$, $v$Celebrities are paid to endorse beauty products.$v$, array[$v$back$v$, $v$promote$v$]::text[], array[$v$condemn$v$]::text[], '7.5'),
  ($v$saturation$v$, 'n', $v$/ˌsætʃəˈreɪʃn/$v$, $v$The point at which no more can be absorbed; oversupply.$v$, $v$Advertising saturation makes consumers tune out.$v$, array[$v$glut$v$, $v$overload$v$]::text[], '{}'::text[], '8.0'),
  ($v$objective$v$, 'adj', $v$/əbˈdʒektɪv/$v$, $v$Not influenced by personal feelings; unbiased.$v$, $v$Good journalism strives to be objective.$v$, array[$v$impartial$v$, $v$neutral$v$]::text[], array[$v$biased$v$, $v$subjective$v$]::text[], '7.0'),
  ($v$persuasive$v$, 'adj', $v$/pəˈsweɪsɪv/$v$, $v$Good at making people believe or do something.$v$, $v$The campaign’s persuasive imagery boosted sales.$v$, array[$v$convincing$v$, $v$compelling$v$]::text[], array[$v$unconvincing$v$]::text[], '7.0'),
  ($v$scrutiny$v$, 'n', $v$/ˈskruːtəni/$v$, $v$Close, critical examination.$v$, $v$Public figures live under constant media scrutiny.$v$, array[$v$examination$v$, $v$inspection$v$]::text[], '{}'::text[], '7.5'),
  ($v$censorship$v$, 'n', $v$/ˈsensəʃɪp/$v$, $v$The suppression of speech or media content.$v$, $v$Internet censorship limits access to independent news.$v$, array[$v$suppression$v$, $v$restriction$v$]::text[], array[$v$free speech$v$]::text[], '7.5'),
  ($v$advertisement$v$, 'n', $v$/ədˈvɜːtɪsmənt/$v$, $v$A notice or film promoting a product or service.$v$, $v$Children are exposed to thousands of advertisements a year.$v$, array[$v$advert$v$, $v$commercial$v$]::text[], '{}'::text[], '6.5'),
  ($v$exposure$v$, 'n', $v$/ɪkˈspəʊʒə/$v$, $v$The state of being seen or experienced widely.$v$, $v$Online platforms give small brands global exposure.$v$, array[$v$publicity$v$, $v$visibility$v$]::text[], '{}'::text[], '7.0'),
  ($v$superficial$v$, 'adj', $v$/ˌsuːpəˈfɪʃl/$v$, $v$Shallow; lacking depth or thoroughness.$v$, $v$Rolling news often gives only superficial analysis.$v$, array[$v$shallow$v$, $v$cursory$v$]::text[], array[$v$profound$v$, $v$thorough$v$]::text[], '7.5'),
  ($v$viral$v$, 'adj', $v$/ˈvaɪrəl/$v$, $v$Spreading rapidly and widely on the internet.$v$, $v$The clip went viral within hours of being posted.$v$, array[$v$widespread$v$]::text[], '{}'::text[], '6.5'),
  ($v$distort$v$, 'v', $v$/dɪˈstɔːt/$v$, $v$To give a misleading or false account of something.$v$, $v$Selective editing can distort what really happened.$v$, array[$v$misrepresent$v$, $v$twist$v$]::text[], array[$v$clarify$v$]::text[], '7.5'),
  ($v$subscription$v$, 'n', $v$/səbˈskrɪpʃn/$v$, $v$An arrangement to receive a service for regular payment.$v$, $v$Many newspapers now rely on digital subscriptions.$v$, array[$v$membership$v$]::text[], '{}'::text[], '6.5'),
  ($v$propagate$v$, 'v', $v$/ˈprɒpəɡeɪt/$v$, $v$To spread and promote an idea widely.$v$, $v$Rumours propagate quickly across messaging apps.$v$, array[$v$spread$v$, $v$disseminate$v$]::text[], array[$v$suppress$v$]::text[], '8.0'),
  ($v$tabloid$v$, 'n', $v$/ˈtæblɔɪd/$v$, $v$A popular newspaper focusing on sensational stories.$v$, $v$Tabloids prioritise celebrity gossip over hard news.$v$, array[$v$gutter press$v$]::text[], array[$v$broadsheet$v$]::text[], '7.5'),
  ($v$consumerism$v$, 'n', $v$/kənˈsjuːmərɪzəm/$v$, $v$A preoccupation with buying consumer goods.$v$, $v$Advertising fuels a culture of relentless consumerism.$v$, array[$v$materialism$v$]::text[], '{}'::text[], '8.0'),
  ($v$accurate$v$, 'adj', $v$/ˈækjərət/$v$, $v$Correct in all details; free from error.$v$, $v$Reporters have a duty to provide accurate information.$v$, array[$v$precise$v$, $v$correct$v$]::text[], array[$v$inaccurate$v$]::text[], '6.5'),
  ($v$watchdog$v$, 'n', $v$/ˈwɒtʃdɒɡ/$v$, $v$A person or group that monitors others’ conduct.$v$, $v$A media watchdog flagged the misleading advert.$v$, array[$v$monitor$v$, $v$regulator$v$]::text[], '{}'::text[], '7.5'),
  ($v$stereotype$v$, 'v', $v$/ˈsteriətaɪp/$v$, $v$To portray a group in a fixed, oversimplified way.$v$, $v$Adverts often stereotype men and women in outdated roles.$v$, array[$v$pigeonhole$v$, $v$typecast$v$]::text[], '{}'::text[], '7.5'),
  ($v$hype$v$, 'n', $v$/haɪp/$v$, $v$Intensive promotion that exaggerates importance.$v$, $v$The product never lived up to the marketing hype.$v$, array[$v$publicity$v$, $v$ballyhoo$v$]::text[], '{}'::text[], '7.0'),
  ($v$intrusive$v$, 'adj', $v$/ɪnˈtruːsɪv/$v$, $v$Disturbing privacy by entering where unwelcome.$v$, $v$Pop-up ads are widely seen as intrusive.$v$, array[$v$invasive$v$, $v$obtrusive$v$]::text[], array[$v$unobtrusive$v$]::text[], '7.5'),
  ($v$disseminate$v$, 'v', $v$/dɪˈsemɪneɪt/$v$, $v$To spread information widely.$v$, $v$The internet lets anyone disseminate news instantly.$v$, array[$v$circulate$v$, $v$broadcast$v$]::text[], array[$v$withhold$v$]::text[], '8.5'),
  ($v$target audience$v$, 'phrase', $v$/ˈtɑːɡɪt ˈɔːdiəns/$v$, $v$The specific group a product or message is aimed at.$v$, $v$The campaign was tailored to a teenage target audience.$v$, '{}'::text[], '{}'::text[], '6.5')
) as w(word, pos, ipa, def, ex, syn, ant, band)
where d.slug = 'media'
on conflict (deck_id, word) do nothing;

-- ── Travel & Tourism (29) ──
insert into vocabulary_words (deck_id, word, part_of_speech, ipa, definition, example, synonyms, antonyms, band_level)
select d.id, w.word, w.pos, w.ipa, w.def, w.ex, w.syn, w.ant, w.band
from vocabulary_decks d
cross join (values
  ($v$destination$v$, 'n', $v$/ˌdestɪˈneɪʃn/$v$, $v$The place to which someone is travelling.$v$, $v$The island has become a top tourist destination.$v$, array[$v$place$v$, $v$resort$v$]::text[], array[$v$origin$v$]::text[], '6.5'),
  ($v$itinerary$v$, 'n', $v$/aɪˈtɪnərəri/$v$, $v$A planned route or schedule of a journey.$v$, $v$Our itinerary packed three cities into five days.$v$, array[$v$schedule$v$, $v$route$v$]::text[], '{}'::text[], '7.0'),
  ($v$ecotourism$v$, 'n', $v$/ˌiːkəʊˈtʊərɪzəm/$v$, $v$Responsible travel to natural areas that protects them.$v$, $v$Ecotourism funds the conservation of the rainforest.$v$, array[$v$green tourism$v$]::text[], '{}'::text[], '7.5'),
  ($v$excursion$v$, 'n', $v$/ɪkˈskɜːʃn/$v$, $v$A short trip, usually for pleasure.$v$, $v$The hotel offers daily excursions to nearby ruins.$v$, array[$v$outing$v$, $v$day trip$v$]::text[], '{}'::text[], '7.0'),
  ($v$picturesque$v$, 'adj', $v$/ˌpɪktʃəˈresk/$v$, $v$Visually attractive, especially in a quaint way.$v$, $v$We stayed in a picturesque fishing village.$v$, array[$v$scenic$v$, $v$charming$v$]::text[], array[$v$ugly$v$, $v$drab$v$]::text[], '7.5'),
  ($v$hospitality$v$, 'n', $v$/ˌhɒspɪˈtæləti/$v$, $v$Friendly, generous treatment of guests.$v$, $v$The region is famous for its warm hospitality.$v$, array[$v$friendliness$v$, $v$welcome$v$]::text[], array[$v$hostility$v$]::text[], '7.0'),
  ($v$overcrowded$v$, 'adj', $v$/ˌəʊvəˈkraʊdɪd/$v$, $v$Filled with too many people.$v$, $v$Famous landmarks are often unpleasantly overcrowded.$v$, array[$v$congested$v$, $v$packed$v$]::text[], array[$v$deserted$v$]::text[], '6.5'),
  ($v$affordable$v$, 'adj', $v$/əˈfɔːdəbl/$v$, $v$Reasonably priced; within one’s means.$v$, $v$Budget airlines have made travel far more affordable.$v$, array[$v$inexpensive$v$, $v$reasonable$v$]::text[], array[$v$expensive$v$]::text[], '6.5'),
  ($v$exotic$v$, 'adj', $v$/ɪɡˈzɒtɪk/$v$, $v$Strikingly unusual or foreign, especially in an exciting way.$v$, $v$Travellers increasingly seek out exotic destinations.$v$, array[$v$unusual$v$, $v$foreign$v$]::text[], array[$v$familiar$v$, $v$ordinary$v$]::text[], '7.0'),
  ($v$accommodation$v$, 'n', $v$/əˌkɒməˈdeɪʃn/$v$, $v$A place to stay, such as a hotel or rented room.$v$, $v$Affordable accommodation is scarce during festivals.$v$, array[$v$lodging$v$, $v$housing$v$]::text[], '{}'::text[], '6.5'),
  ($v$venture$v$, 'v', $v$/ˈventʃə/$v$, $v$To go somewhere despite possible risk.$v$, $v$Few tourists venture beyond the main resort.$v$, array[$v$dare$v$, $v$set out$v$]::text[], '{}'::text[], '7.5'),
  ($v$scenic$v$, 'adj', $v$/ˈsiːnɪk/$v$, $v$Providing attractive views of natural scenery.$v$, $v$We took the longer but more scenic coastal route.$v$, array[$v$picturesque$v$, $v$panoramic$v$]::text[], array[$v$drab$v$]::text[], '7.0'),
  ($v$cosmopolitan$v$, 'adj', $v$/ˌkɒzməˈpɒlɪtən/$v$, $v$Familiar with and comprising people from many cultures.$v$, $v$London is one of the world’s most cosmopolitan cities.$v$, array[$v$multicultural$v$, $v$worldly$v$]::text[], array[$v$provincial$v$]::text[], '8.0'),
  ($v$landmark$v$, 'n', $v$/ˈlændmɑːk/$v$, $v$A famous or easily recognised building or feature.$v$, $v$The tower is the city’s most photographed landmark.$v$, array[$v$monument$v$, $v$attraction$v$]::text[], '{}'::text[], '6.5'),
  ($v$off the beaten track$v$, 'phrase', $v$/ɒf ðə ˈbiːtn træk/$v$, $v$In a place far from where people usually go.$v$, $v$We prefer villages off the beaten track to busy resorts.$v$, array[$v$remote$v$, $v$secluded$v$]::text[], '{}'::text[], '7.5'),
  ($v$wanderlust$v$, 'n', $v$/ˈwɒndəlʌst/$v$, $v$A strong desire to travel and explore the world.$v$, $v$Her wanderlust took her to over forty countries.$v$, array[$v$travel bug$v$]::text[], '{}'::text[], '8.0'),
  ($v$seasonal$v$, 'adj', $v$/ˈsiːzənl/$v$, $v$Occurring or varying with the seasons.$v$, $v$Tourism here is highly seasonal, peaking in summer.$v$, array[$v$periodic$v$]::text[], array[$v$year-round$v$]::text[], '7.0'),
  ($v$commercialised$v$, 'adj', $v$/kəˈmɜːʃəlaɪzd/$v$, $v$Made too focused on making money, losing authenticity.$v$, $v$The once-quiet beach is now heavily commercialised.$v$, array[$v$exploited$v$]::text[], array[$v$unspoilt$v$]::text[], '7.5'),
  ($v$immerse$v$, 'v', $v$/ɪˈmɜːs/$v$, $v$To involve oneself deeply in an activity or environment.$v$, $v$Living abroad lets you immerse yourself in a new culture.$v$, array[$v$engross$v$, $v$absorb$v$]::text[], '{}'::text[], '8.0'),
  ($v$breathtaking$v$, 'adj', $v$/ˈbreθteɪkɪŋ/$v$, $v$Astonishing or awe-inspiring, especially in beauty.$v$, $v$The view from the summit was breathtaking.$v$, array[$v$stunning$v$, $v$spectacular$v$]::text[], array[$v$unremarkable$v$]::text[], '7.0'),
  ($v$expedition$v$, 'n', $v$/ˌekspəˈdɪʃn/$v$, $v$A journey undertaken for a particular purpose.$v$, $v$They joined an expedition to the polar ice cap.$v$, array[$v$journey$v$, $v$voyage$v$]::text[], '{}'::text[], '7.0'),
  ($v$unspoilt$v$, 'adj', $v$/ˌʌnˈspɔɪlt/$v$, $v$Not changed or damaged; still in a natural state.$v$, $v$The coastline remains remarkably unspoilt.$v$, array[$v$pristine$v$, $v$untouched$v$]::text[], array[$v$developed$v$, $v$spoilt$v$]::text[], '7.5'),
  ($v$migrate$v$, 'v', $v$/maɪˈɡreɪt/$v$, $v$To move from one region or habitat to another.$v$, $v$Some retirees migrate south for the warmer winters.$v$, array[$v$relocate$v$, $v$move$v$]::text[], array[$v$stay$v$]::text[], '6.5'),
  ($v$vibrant$v$, 'adj', $v$/ˈvaɪbrənt/$v$, $v$Full of energy, life and colour.$v$, $v$The market is a vibrant hub of local life.$v$, array[$v$lively$v$, $v$bustling$v$]::text[], array[$v$dull$v$, $v$lifeless$v$]::text[], '7.0'),
  ($v$authentic$v$, 'adj', $v$/ɔːˈθentɪk/$v$, $v$Genuine; truly representing its origins.$v$, $v$Tourists increasingly crave authentic local experiences.$v$, array[$v$genuine$v$, $v$real$v$]::text[], array[$v$fake$v$, $v$artificial$v$]::text[], '7.0'),
  ($v$rejuvenate$v$, 'v', $v$/rɪˈdʒuːvəneɪt/$v$, $v$To make someone feel younger and full of energy again.$v$, $v$A week by the sea rejuvenated the whole family.$v$, array[$v$refresh$v$, $v$revitalise$v$]::text[], array[$v$exhaust$v$]::text[], '8.0'),
  ($v$remote$v$, 'adj', $v$/rɪˈməʊt/$v$, $v$Far away from towns or other people; isolated.$v$, $v$The lodge sits in a remote mountain valley.$v$, array[$v$isolated$v$, $v$secluded$v$]::text[], array[$v$accessible$v$, $v$central$v$]::text[], '6.5'),
  ($v$infrastructure$v$, 'n', $v$/ˈɪnfrəstrʌktʃə/$v$, $v$Basic facilities such as transport and utilities.$v$, $v$Poor transport infrastructure deters foreign visitors.$v$, array[$v$facilities$v$]::text[], '{}'::text[], '7.0'),
  ($v$bustling$v$, 'adj', $v$/ˈbʌslɪŋ/$v$, $v$Full of energetic and noisy activity.$v$, $v$We wandered through the bustling night market.$v$, array[$v$busy$v$, $v$lively$v$]::text[], array[$v$quiet$v$, $v$sleepy$v$]::text[], '7.5')
