  ($v$derive$v$, 'v', $v$/dɪˈraɪv/$v$, $v$To obtain something from a source.$v$, $v$Much of our energy is still derived from coal.$v$, array[$v$obtain$v$, $v$gain$v$]::text[], '{}'::text[], '7.0'),
  ($v$establish$v$, 'v', $v$/ɪˈstæblɪʃ/$v$, $v$To set up or prove something firmly.$v$, $v$Researchers established a clear link between the two.$v$, array[$v$set up$v$, $v$demonstrate$v$]::text[], array[$v$abolish$v$]::text[], '6.5'),
  ($v$evident$v$, 'adj', $v$/ˈevɪdənt/$v$, $v$Clearly seen or understood; obvious.$v$, $v$It is evident that early intervention works best.$v$, array[$v$obvious$v$, $v$apparent$v$]::text[], array[$v$unclear$v$]::text[], '7.0'),
  ($v$factor$v$, 'n', $v$/ˈfæktə/$v$, $v$One element contributing to a result.$v$, $v$Cost is the decisive factor for most consumers.$v$, array[$v$element$v$, $v$cause$v$]::text[], '{}'::text[], '6.5'),
  ($v$interpret$v$, 'v', $v$/ɪnˈtɜːprɪt/$v$, $v$To explain the meaning of something.$v$, $v$The data can be interpreted in several ways.$v$, array[$v$explain$v$, $v$construe$v$]::text[], array[$v$misread$v$]::text[], '7.0'),
  ($v$principle$v$, 'n', $v$/ˈprɪnsəpl/$v$, $v$A fundamental truth or rule guiding behaviour.$v$, $v$The system rests on the principle of fairness.$v$, array[$v$rule$v$, $v$tenet$v$]::text[], '{}'::text[], '7.0'),
  ($v$sufficient$v$, 'adj', $v$/səˈfɪʃnt/$v$, $v$Enough for a particular purpose.$v$, $v$There is sufficient evidence to justify the policy.$v$, array[$v$adequate$v$, $v$ample$v$]::text[], array[$v$insufficient$v$]::text[], '7.0'),
  ($v$consequently$v$, 'adv', $v$/ˈkɒnsɪkwəntli/$v$, $v$As a result; therefore.$v$, $v$Demand fell and prices consequently dropped.$v$, array[$v$therefore$v$, $v$thus$v$]::text[], '{}'::text[], '7.0'),
  ($v$framework$v$, 'n', $v$/ˈfreɪmwɜːk/$v$, $v$A basic structure underlying a system or idea.$v$, $v$The treaty sets out a framework for cooperation.$v$, array[$v$structure$v$, $v$system$v$]::text[], '{}'::text[], '7.5'),
  ($v$hypothesis$v$, 'n', $v$/haɪˈpɒθəsɪs/$v$, $v$A proposed explanation tested by research.$v$, $v$The experiment supported the original hypothesis.$v$, array[$v$theory$v$, $v$proposition$v$]::text[], '{}'::text[], '7.5'),
  ($v$phenomenon$v$, 'n', $v$/fəˈnɒmɪnən/$v$, $v$A fact or situation that is observed to exist.$v$, $v$Mass migration is a global phenomenon.$v$, array[$v$occurrence$v$, $v$event$v$]::text[], '{}'::text[], '7.5'),
  ($v$criteria$v$, 'n', $v$/kraɪˈtɪəriə/$v$, $v$Standards by which something is judged.$v$, $v$Applicants are assessed against strict criteria.$v$, array[$v$standards$v$, $v$benchmarks$v$]::text[], '{}'::text[], '7.0'),
  ($v$substantial$v$, 'adj', $v$/səbˈstænʃl/$v$, $v$Large in amount, size or importance.$v$, $v$The charity received a substantial donation.$v$, array[$v$considerable$v$, $v$sizeable$v$]::text[], array[$v$minor$v$, $v$slight$v$]::text[], '7.5'),
