  ($v$advocate$v$, 'n', $v$/ˈædvəkət/$v$, $v$A person who publicly supports a cause.$v$, $v$She is a leading advocate of renewable energy.$v$, array[$v$supporter$v$, $v$proponent$v$]::text[], array[$v$opponent$v$]::text[], '7.5'),
