  ($v$correlation$v$, 'n', $v$/ˌkɒrəˈleɪʃn/$v$, $v$A mutual relationship between two things.$v$, $v$There is a strong correlation between income and health.$v$, array[$v$connection$v$, $v$link$v$]::text[], '{}'::text[], '8.0'),
  ($v$enhance$v$, 'v', $v$/ɪnˈhɑːns/$v$, $v$To improve the quality or value of something.$v$, $v$Technology can greatly enhance the learning experience.$v$, array[$v$improve$v$, $v$boost$v$]::text[], array[$v$diminish$v$, $v$weaken$v$]::text[], '7.0'),
  ($v$implication$v$, 'n', $v$/ˌɪmplɪˈkeɪʃn/$v$, $v$A likely consequence or effect.$v$, $v$The ruling has serious implications for privacy.$v$, array[$v$consequence$v$, $v$ramification$v$]::text[], '{}'::text[], '7.5'),
  ($v$validity$v$, 'n', $v$/vəˈlɪdəti/$v$, $v$The quality of being logically sound or legally acceptable.$v$, $v$Critics questioned the validity of the survey.$v$, array[$v$soundness$v$, $v$legitimacy$v$]::text[], array[$v$invalidity$v$]::text[], '8.0'),
