  ($v$paradigm$v$, 'n', $v$/ˈpærədaɪm/$v$, $v$A typical pattern or model of something.$v$, $v$Remote work has shifted the paradigm of office life.$v$, array[$v$model$v$, $v$pattern$v$]::text[], '{}'::text[], '8.5'),
  ($v$cumulative$v$, 'adj', $v$/ˈkjuːmjələtɪv/$v$, $v$Increasing by successive additions.$v$, $v$The cumulative effect of small savings is huge.$v$, array[$v$accumulating$v$, $v$collective$v$]::text[], '{}'::text[], '8.0')
