from vocabulary_decks d
cross join (values
  ($v$furthermore$v$, 'adv', $v$/ˌfɜːðəˈmɔː/$v$, $v$In addition; used to add a supporting point.$v$, $v$The plan is costly; furthermore, it may not even work.$v$, array[$v$moreover$v$, $v$in addition$v$]::text[], '{}'::text[], '7.0'),
  ($v$nevertheless$v$, 'adv', $v$/ˌnevəðəˈles/$v$, $v$In spite of what has just been said.$v$, $v$The risks are real; nevertheless, the benefits outweigh them.$v$, array[$v$nonetheless$v$, $v$even so$v$]::text[], '{}'::text[], '7.5'),
  ($v$consequently$v$, 'adv', $v$/ˈkɒnsɪkwəntli/$v$, $v$As a result of something just mentioned.$v$, $v$Rents rose sharply and, consequently, many families moved.$v$, array[$v$therefore$v$, $v$as a result$v$]::text[], '{}'::text[], '7.0'),
  ($v$conversely$v$, 'adv', $v$/ˈkɒnvɜːsli/$v$, $v$Introducing a statement that reverses the previous one.$v$, $v$City life is convenient; conversely, it can be stressful.$v$, array[$v$on the other hand$v$, $v$in contrast$v$]::text[], '{}'::text[], '8.0'),
  ($v$moreover$v$, 'adv', $v$/mɔːrˈəʊvə/$v$, $v$Used to add information that strengthens a point.$v$, $v$The drug is expensive; moreover, it has side effects.$v$, array[$v$furthermore$v$, $v$besides$v$]::text[], '{}'::text[], '7.0'),
  ($v$notably$v$, 'adv', $v$/ˈnəʊtəbli/$v$, $v$Used to highlight an important example.$v$, $v$Several countries, notably Japan, face ageing populations.$v$, array[$v$particularly$v$, $v$especially$v$]::text[], '{}'::text[], '7.5'),
  ($v$whereas$v$, 'adv', $v$/weərˈæz/$v$, $v$In contrast or comparison with the fact that.$v$, $v$The north is industrial, whereas the south is agricultural.$v$, array[$v$while$v$, $v$in contrast$v$]::text[], '{}'::text[], '7.0'),
  ($v$albeit$v$, 'adv', $v$/ɔːlˈbiːɪt/$v$, $v$Although; even though (introducing a concession).$v$, $v$The reform succeeded, albeit at considerable cost.$v$, array[$v$although$v$, $v$even if$v$]::text[], '{}'::text[], '8.0'),
  ($v$notwithstanding$v$, 'adv', $v$/ˌnɒtwɪθˈstændɪŋ/$v$, $v$In spite of; nevertheless.$v$, $v$Notwithstanding the criticism, the policy continued.$v$, array[$v$despite$v$, $v$regardless$v$]::text[], '{}'::text[], '8.5'),
  ($v$thereby$v$, 'adv', $v$/ˌðeəˈbaɪ/$v$, $v$By that means; as a result of that.$v$, $v$Recycling reduces waste, thereby protecting resources.$v$, array[$v$thus$v$, $v$in that way$v$]::text[], '{}'::text[], '8.0'),
  ($v$hence$v$, 'adv', $v$/hens/$v$, $v$For this reason; therefore.$v$, $v$The data are incomplete; hence the cautious conclusion.$v$, array[$v$therefore$v$, $v$thus$v$]::text[], '{}'::text[], '7.5'),
  ($v$for instance$v$, 'phrase', $v$/fər ˈɪnstəns/$v$, $v$Used to introduce an example.$v$, $v$Many habits, for instance smoking, are hard to break.$v$, array[$v$for example$v$, $v$such as$v$]::text[], '{}'::text[], '6.5'),
  ($v$in addition$v$, 'phrase', $v$/ɪn əˈdɪʃn/$v$, $v$Used to add another point.$v$, $v$In addition, the scheme creates thousands of jobs.$v$, array[$v$furthermore$v$, $v$also$v$]::text[], '{}'::text[], '6.5'),
  ($v$on the other hand$v$, 'phrase', $v$/ɒn ðə ˈʌðə hænd/$v$, $v$Used to present a contrasting view.$v$, $v$On the other hand, some argue the opposite.$v$, array[$v$conversely$v$, $v$however$v$]::text[], '{}'::text[], '6.5'),
  ($v$as a result$v$, 'phrase', $v$/əz ə rɪˈzʌlt/$v$, $v$Because of something; consequently.$v$, $v$Sales fell and, as a result, staff were let go.$v$, array[$v$consequently$v$, $v$therefore$v$]::text[], '{}'::text[], '6.5'),
  ($v$in contrast$v$, 'phrase', $v$/ɪn ˈkɒntrɑːst/$v$, $v$Used to compare two opposing things.$v$, $v$In contrast, rural areas have lost population.$v$, array[$v$conversely$v$, $v$on the other hand$v$]::text[], '{}'::text[], '7.0'),
  ($v$to illustrate$v$, 'phrase', $v$/tu ˈɪləstreɪt/$v$, $v$Used to introduce a clarifying example.$v$, $v$To illustrate, consider the case of online banking.$v$, array[$v$for example$v$, $v$by way of example$v$]::text[], '{}'::text[], '7.5'),
  ($v$by and large$v$, 'phrase', $v$/baɪ ən lɑːdʒ/$v$, $v$On the whole; generally speaking.$v$, $v$By and large, the reforms have been welcomed.$v$, array[$v$generally$v$, $v$on the whole$v$]::text[], '{}'::text[], '7.5'),
  ($v$owing to$v$, 'phrase', $v$/ˈəʊɪŋ tu/$v$, $v$Because of; as a result of.$v$, $v$Owing to bad weather, the event was cancelled.$v$, array[$v$due to$v$, $v$because of$v$]::text[], '{}'::text[], '7.0'),
  ($v$in essence$v$, 'phrase', $v$/ɪn ˈesns/$v$, $v$Used to state the most basic point.$v$, $v$In essence, the argument boils down to fairness.$v$, array[$v$fundamentally$v$, $v$basically$v$]::text[], '{}'::text[], '7.5'),
